  "title": "Defense Intelligence Authority and Board Representation",
  "setting": "National Security Council, January 1961, during the administration’s final two weeks.",
  "decider": "The National Security Council",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The National Security Council",
  "agent_role": "decide",
  "situation": "The Joint Study Group on Foreign Intelligence Activities has submitted recommendations, some agreed and others unresolved. The recommendations include changing the military intelligence organization within the Department of Defense and changing representation on the U.S. Intelligence Board. The National Security Council Intelligence Directives refer to the Military Services rather than the Secretary of Defense, and their provisions cover the Board’s organization. The President favors greater integration, while the Military Services have personnel and experience in intelligence, and the Director of Central Intelligence has raised concern about changing representation before Defense has adequate intelligence support. The administration has two weeks remaining, and the question is how far to reorganize intelligence during that period.",
  "question": "What should the National Security Council do about revising the National Security Council Intelligence Directives and changing U.S. Intelligence Board membership during the administration’s final weeks?",
  "facts": [
    {
      "id": "F1",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The National Security Council Intelligence Directives refer to the Military Services rather than the Secretary of Defense, and amendments were proposed to give the Secretary authority to reorganize military intelligence within the Department of Defense.",
      "spans": [
        "src:a6cfee20e127#p1.6"
      ]
    },
    {
      "id": "F2",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The Joint Study Group recommended that the Secretary of Defense and the Joint Chiefs of Staff, rather than the Military Services, be represented on the U.S. Intelligence Board.",
      "spans": [
        "src:a6cfee20e127#p2.2"
      ]
    },
    {
      "id": "F3",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The Military Services opposed the proposed change in Board membership, and the Director of Central Intelligence also opposed it.",
      "spans": [
        "src:a6cfee20e127#p2.2"
      ]
    },
    {
      "id": "F4",
      "kind": "capability",
      "status": "assessed",
      "fact": "The President believed that about $1.1 billion was being spent on the Department of Defense intelligence function and that the function should be performed at less expense.",
      "spans": [
        "src:a6cfee20e127#p2.3"
      ]
    },
    {
      "id": "F5",
      "kind": "capability",
      "status": "assessed",
      "fact": "The President believed that separate intelligence organizations for each Military Service impeded integration and strategic planning.",
      "spans": [
        "src:a6cfee20e127#p2.3"
      ]
    },
    {
      "id": "F6",
      "kind": "capability",
      "status": "assessed",
      "fact": "The Military Services had personnel, competence, and intelligence background, while the Director of Central Intelligence believed a Secretary of Defense representative would lack adequate experience and support until Defense intelligence organization changed.",
      "spans": [
        "src:a6cfee20e127#p2.4"
      ]
    },
    {
      "id": "F7",
      "kind": "capability",
      "status": "assessed",
      "fact": "The Secretary of Defense supported the proposed Board-membership change and believed a Defense representative could prepare the Department’s position for Board meetings.",
      "spans": [
        "src:a6cfee20e127#p2.2",
        "src:a6cfee20e127#p3.3"
      ]
    },
    {
      "id": "F8",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The administration had two weeks remaining, and the policy question was how far to reorganize intelligence during that period.",
      "spans": [
        "src:a6cfee20e127#p4.2"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The National Security Council should authorize immediate revisions to the directives and U.S. Intelligence Board membership, changing Defense authority and representation during its final weeks.",
      "move": "act",
      "disposition": "authorize",
      "irreversible": true
    },
    "O2": {
      "do": "The National Security Council should decline immediate revisions to the directives and U.S. Intelligence Board membership, retaining current Defense authority and representation during its final weeks.",
      "move": "act",
      "disposition": "decline",
      "irreversible": false
    },
    "O3": {
      "do": "The National Security Council should ask the Secretary of Defense to submit recommendations on directives and U.S. Intelligence Board membership for consideration at the next Council meeting.",
      "move": "ask",
      "to": "The Secretary of Defense",
      "disposition": "defer",
      "irreversible": false
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O3",
  "authored_options": [
    "O1",
    "O2"
  ],
  "no_opposite_reason": ""
}

